    // ═══ LIFECYCLE ═══
    protected override async Task OnInitializedAsync()
    {
        try
        {
            isLoading = true;
            maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JS);
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel") ?? "02";

            // Đọc năm học (key "selectedNamHoc") – giống DotNhapDiem
            selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc") ?? "2025-2026";
            if (!string.IsNullOrEmpty(selectedNamHoc))
            {
                var parts = selectedNamHoc.Split('-');
                if (parts.Length >= 1 && int.TryParse(parts[0].Trim(), out var parsedYear))
                    selectedNamHocInt = parsedYear;
            }

            // Đọc học kỳ (key "selectedHocKy") – giống DotNhapDiem
            var hocKyStr = await BrowserStorageService.GetItem(JS, "selectedHocKy");
            if (!string.IsNullOrEmpty(hocKyStr) && int.TryParse(hocKyStr, out var savedHocKy))
                selectedHocKy = savedHocKy;
            else
                selectedHocKy = DateTime.Now.Month >= 8 && DateTime.Now.Month <= 12 ? 1 : 2;

            // Lấy ID người dùng (dùng cho NopNangLucPhamChatC1)
            var idStr = await BrowserStorageService.GetItem(JS, "userId");
            idNguoiDung = int.TryParse(idStr, out var uid) ? uid : 0;

            if (string.IsNullOrEmpty(maTruongBo))
            {
                await ShowToast("Không tìm thấy mã trường. Vui lòng đăng nhập lại.", "error");
                Nav.NavigateTo("/");
                return;
            }

            await LoadData();
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); }
        finally { isLoading = false; StateHasChanged(); }
    }

    // ═══ LOAD DATA: Phase 1 – hiển thị ngay, Phase 2 – load stats background ═══
    private async Task LoadData()
    {
        try
        {
            lopStatsLoaded.Clear();

            // ── Phase 1: song song lấy danh sách khối + lớp – nhanh ──
            var t_khoi = TruongService.hGetDanhSachKhoi(maTruongBo!, selectedCapHoc!);
            var t_lop  = TruongService.hGetDanhSachLop(maTruongBo!, selectedCapHoc!, selectedNamHoc!);
            await Task.WhenAll(t_khoi, t_lop);

            var khoiList = t_khoi.Result;
            var lopList  = t_lop.Result;

            danhSachKhoi = khoiList.Select(k => new KhoiItem
            {
                Ten = k.TenKhoi, MaKhoi = k.MaKhoiBo,
                IsExpanded = false, IsSelected = false
            }).ToList();
            if (danhSachKhoi.Any()) danhSachKhoi.First().IsExpanded = true;

            // Build list với Progress = 0 (chưa có stats) – render ngay
            danhSachLop = lopList.Select(l => new LopItem
            {
                Id = l.MaLopBo, Ten = l.TenLop,
                Khoi = l.MaKhoiBo, IsSelected = false
            }).ToList();

            if (!IsCapTieuHoc)
            {
                tkDanhSachKhoi = danhSachKhoi.Select(k => new KhoiItem
                {
                    Ten = k.Ten, MaKhoi = k.MaKhoi,
                    IsExpanded = false, IsSelected = false
                }).ToList();
                if (tkDanhSachKhoi.Any()) tkDanhSachKhoi.First().IsExpanded = true;

                tkDanhSachLop = danhSachLop.Select(l => new LopItem
                {
                    Id = l.Id, Ten = l.Ten, Khoi = l.Khoi, IsSelected = false
                }).ToList();
            }

            // Hiển thị ngay, tắt overlay
            isLoading = false;
            StateHasChanged();

            // ── Phase 2: load stats nền, từng lớp xong update liền ──
            _ = LoadStatsBackground();
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); }
    }

    /// <summary>
    /// Load thống kê tiến độ từng lớp song song trong nền.
    /// Mỗi lớp xong → update card ngay qua InvokeAsync(StateHasChanged).
    /// </summary>
    private async Task LoadStatsBackground()
    {
        isLoadingStats = true;
        try
        {
            // Mỗi lớp chạy song song, xong lớp nào update UI lớp đó ngay
            var tasks = danhSachLop.Select(async lop =>
            {
                try
                {
                    decimal prog = 0, progNL = 0;

                    if (IsCapTieuHoc)
                    {
                        var tDK = DiemService.GetThongKeDanhGiaDinhKyTheoLopCapTieuHoc(
                                      maTruongBo!, lop.Id, selectedHocKy, selectedNamHoc!);
                        var tNL = DiemService.GetThongKeDanhGiaNangLucTheoLopCapTieuHoc(
                                      maTruongBo!, lop.Id, selectedHocKy, selectedNamHoc!);
                        await Task.WhenAll(tDK, tNL);
                        prog   = tDK.Result.FirstOrDefault()?.PhanTramDaNop ?? 0;
                        progNL = tNL.Result.FirstOrDefault()?.PhanTramDaNop ?? 0;
                    }
                    else
                    {
                        var tk = await DiemService.GetThongKeNopBaiTheoLop_C2_3(
                                     maTruongBo!, lop.Id, selectedHocKy, selectedNamHoc!);
                        prog = tk.FirstOrDefault()?.PhanTramDaNop ?? 0;
                    }

                    lop.Progress        = prog;
                    lop.ProgressNangLuc = progNL;
                    lopStatsLoaded.Add(lop.Id);

                    // Cập nhật UI cho lớp này ngay
                    await InvokeAsync(StateHasChanged);
                }
                catch { lopStatsLoaded.Add(lop.Id); } // vẫn đánh dấu loaded để không spinner mãi
            });

            await Task.WhenAll(tasks);
        }
        finally
        {
            isLoadingStats = false;
            await InvokeAsync(StateHasChanged);
        }
    }

