    private async Task RefreshStudentView()
    {
        isLoading = true; StateHasChanged();
        try
        {
            List<DiemData.HocSinhNopBaiDTO> ds;

            if (IsCapTieuHoc && currentSubTab == "nangluc")
            {
                ds = await DiemService.GetDanhSachHocSinhNopDanhGiaNangLucTheoLopCapTieuHoc(
                    maTruongBo!, selectedLopId, selectedHocKy, selectedNamHoc!);
            }
            else if (IsCapTieuHoc)
            {
                ds = await DiemService.GetDanhSachHocSinhNopBaiTheoLopCapTieuHoc(
                    maTruongBo!, selectedLopId, selectedHocKy, selectedNamHoc!);
            }
            else
            {
                ds = await DiemService.GetDanhSachHocSinhNopBaiTheoLop_C2_3(
                    maTruongBo!, selectedLopId, selectedHocKy, selectedNamHoc!);
            }

            danhSachHocSinh = ds.Select(h => new HocSinhItem
            {
                MaHocSinhSo = h.MaHocSinhSo,
                HoTen       = h.HoTen,
                NgaySinh    = h.NgaySinh,
                SoDiemDaNop = h.SoDiemDaNop,
                HoanThanh   = h.HoanThanh,
                IsSelected  = false
            }).ToList();
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); }
        finally { isLoading = false; StateHasChanged(); }
    }

    // ═══ VIEW CLASS – Tổng Kết (C2/3) ═══
    private async Task TKViewClass(LopItem lop)
