    // ═══ SELECTION HELPERS ═══
    private int GetSelectedCount()
    {
        if (activeTab == "tongket" && tkCurrentLevel == "Students")
            return tkDanhSachHocSinh.Count(h => h.IsSelected);
        if (currentLevel == "Overview")
            return danhSachKhoi.Count(k => k.IsSelected) + danhSachLop.Count(l => l.IsSelected);
        return danhSachHocSinh.Count(h => h.IsSelected);
    }

    private void ToggleGradeSelection(KhoiItem khoi, bool isSelected)
    {
        khoi.IsSelected = isSelected;
        foreach (var lop in danhSachLop.Where(l => l.Khoi == khoi.MaKhoi))
            lop.IsSelected = isSelected;
    }

    private void ToggleTKGradeSelection(KhoiItem khoi, bool isSelected)
    {
        khoi.IsSelected = isSelected;
        foreach (var lop in tkDanhSachLop.Where(l => l.Khoi == khoi.MaKhoi))
            lop.IsSelected = isSelected;
    }

    private void ToggleSelectAllStudents(ChangeEventArgs e)
    {
        var v = (bool)e.Value!;
        foreach (var hs in danhSachHocSinh) hs.IsSelected = v;
    }

    private void ToggleSelectAllTKStudents(ChangeEventArgs e)
    {
        var v = (bool)e.Value!;
        foreach (var hs in tkDanhSachHocSinh) hs.IsSelected = v;
    }

