    // ═══ MODAL ═══
    private void OpenConfirmModal(string type, string hsSo = "")
    {
        confirmType   = type;
        tkTargetHsSo  = hsSo;
        confirmMessage = type switch
        {
            "SELECTED"   => currentLevel == "Overview"
                              ? $"Bạn sắp nộp điểm cho {GetSelectedCount()} lớp đã chọn."
                              : $"Bạn sắp nộp điểm cho {GetSelectedCount()} học sinh đã chọn.",
            "ALL"        => "Bạn sắp nộp điểm TOÀN TRƯỜNG. Thao tác này không thể hoàn tác.",
            "CLASS"      => $"Bạn sắp nộp điểm cho LỚP {selectedLopTen}.",
            "TK_CLASS"   => $"Bạn sắp nộp TỔNG KẾT cho LỚP {tkSelectedLopTen}.",
            "TK_STUDENT" => $"Bạn sắp nộp TỔNG KẾT cho học sinh {hsSo}.",
            "TK_SELECTED"=> $"Bạn sắp nộp TỔNG KẾT cho {tkDanhSachHocSinh.Count(h => h.IsSelected)} học sinh đã chọn.",
            _ => ""
        };
        showConfirmModal = true;
    }

    private void CloseConfirmModal() => showConfirmModal = false;

    // ═══ SUBMIT ═══
    private async Task HandleSubmit()
    {
        showConfirmModal = false;
        isLoading = true; StateHasChanged();

        try
        {
            // ── Nộp Tổng Kết C2/3 ──
            if (confirmType.StartsWith("TK_"))
            {
                await HandleSubmitTongKet();
                return;
            }

            // ── Nộp Điểm Định Kỳ / Năng Lực ──
            if (IsCapTieuHoc)
            {
                await HandleSubmitCapTieuHoc();
                return;
            }

            // ── C2/3: Nộp Định Kỳ ──
            string apiUrl = TruongHocData.API_KetNoiSGD + "CongNhapDiem/NopDiemC2_3";

            if (confirmType == "ALL")
            {
                var res = await Http.PostAsJsonAsync(apiUrl, BuildRequestC2_3("", ""));
                await ShowToast(res.IsSuccessStatusCode
                    ? "Nộp điểm toàn trường thành công!"
                    : $"Lỗi: {res.StatusCode}", res.IsSuccessStatusCode ? "success" : "error");
            }
            else if (confirmType == "SELECTED")
            {
                if (currentLevel == "Overview")
                {
                    var selected = danhSachLop.Where(l => l.IsSelected).ToList();
                    if (!selected.Any()) { await ShowToast("Vui lòng chọn ít nhất một lớp.", "warning"); return; }
                    int ok = 0, fail = 0;
                    foreach (var lop in selected)
                    {
                        var res = await Http.PostAsJsonAsync(apiUrl, BuildRequestC2_3(lop.Ten, ""));
                        if (res.IsSuccessStatusCode) ok++; else fail++;
                    }
                    await ShowToast($"Thành công: {ok} lớp, thất bại: {fail} lớp.", fail > 0 ? "warning" : "success");
                }
                else
                {
                    var selected = danhSachHocSinh.Where(h => h.IsSelected).ToList();
                    if (!selected.Any()) { await ShowToast("Vui lòng chọn ít nhất một học sinh.", "warning"); return; }
                    int ok = 0, fail = 0;
                    foreach (var hs in selected)
                    {
                        var res = await Http.PostAsJsonAsync(apiUrl, BuildRequestC2_3(selectedLopTen, hs.MaHocSinhSo));
                        if (res.IsSuccessStatusCode) ok++; else fail++;
                    }
                    await ShowToast($"Thành công: {ok} HS, thất bại: {fail} HS.", fail > 0 ? "warning" : "success");
                    if (ok > 0) await RefreshStudentView();
                }
            }
            else if (confirmType == "CLASS")
            {
                var res = await Http.PostAsJsonAsync(apiUrl, BuildRequestC2_3(selectedLopTen, ""));
                if (res.IsSuccessStatusCode)
                {
                    await ShowToast($"Nộp lớp {selectedLopTen} thành công!", "success");
                    await RefreshStudentView();
                }
                else
                {
                    await ShowToast($"Lỗi nộp lớp: {res.StatusCode}", "error");
                }
            }
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); }
        finally { isLoading = false; StateHasChanged(); }
    }

    /// <summary>
    /// Xử lý nộp cho CẤP TIỂU HỌC — phân nhánh theo currentSubTab:
    ///   dinhky  → POST NopDanhGiaDinhKyC1
    ///   nangluc → POST NopNangLucPhamChatC1
    /// </summary>
    private async Task HandleSubmitCapTieuHoc()
    {
        bool isDinhKy = currentSubTab == "dinhky";
        string apiUrl = TruongHocData.API_KetNoiSGD + (isDinhKy
            ? "CongNhapDiem/NopDanhGiaDinhKyC1"
            : "CongNhapDiem/NopNangLucPhamChatC1");

        string loai = isDinhKy ? "Đánh Giá Định Kỳ" : "Năng Lực Phẩm Chất";

        if (confirmType == "ALL")
        {
            // Nộp toàn trường: lặp theo từng lớp
            int ok = 0, fail = 0;
            foreach (var lop in danhSachLop)
            {
                var req  = isDinhKy
                    ? BuildDinhKyC1Request(lop.Ten, "", "")
                    : (object)BuildNangLucC1Request(lop.Ten, "");
                var res = await Http.PostAsJsonAsync(apiUrl, req);
                if (res.IsSuccessStatusCode) ok++; else fail++;
            }
            await ShowToast($"{loai} – Thành công: {ok} lớp, thất bại: {fail} lớp.",
                fail > 0 ? "warning" : "success");
        }
        else if (confirmType == "SELECTED")
        {
            if (currentLevel == "Overview")
            {
                var selected = danhSachLop.Where(l => l.IsSelected).ToList();
                if (!selected.Any()) { await ShowToast("Vui lòng chọn ít nhất một lớp.", "warning"); return; }
                int ok = 0, fail = 0;
                foreach (var lop in selected)
                {
                    var req = isDinhKy
                        ? BuildDinhKyC1Request(lop.Ten, "", "")
                        : (object)BuildNangLucC1Request(lop.Ten, "");
                    var res = await Http.PostAsJsonAsync(apiUrl, req);
                    if (res.IsSuccessStatusCode) ok++; else fail++;
                }
                await ShowToast($"{loai} – Thành công: {ok} lớp, thất bại: {fail} lớp.",
                    fail > 0 ? "warning" : "success");
            }
            else
            {
                var selected = danhSachHocSinh.Where(h => h.IsSelected).ToList();
                if (!selected.Any()) { await ShowToast("Vui lòng chọn ít nhất một học sinh.", "warning"); return; }
                int ok = 0, fail = 0;
                foreach (var hs in selected)
                {
                    var req = isDinhKy
                        ? BuildDinhKyC1Request(selectedLopTen, hs.MaHocSinhSo, "")
                        : (object)BuildNangLucC1Request(selectedLopTen, hs.MaHocSinhSo);
                    var res = await Http.PostAsJsonAsync(apiUrl, req);
                    if (res.IsSuccessStatusCode) ok++; else fail++;
                }
                await ShowToast($"{loai} – Thành công: {ok} HS, thất bại: {fail} HS.",
                    fail > 0 ? "warning" : "success");
                if (ok > 0) await RefreshStudentView();
            }
        }
        else if (confirmType == "CLASS")
        {
            var req = isDinhKy
                ? BuildDinhKyC1Request(selectedLopTen, "", "")
                : (object)BuildNangLucC1Request(selectedLopTen, "");
            var res = await Http.PostAsJsonAsync(apiUrl, req);
            if (res.IsSuccessStatusCode)
            {
                await ShowToast($"{loai} – Lớp {selectedLopTen} thành công!", "success");
                await RefreshStudentView();
            }
            else
            {
                await ShowToast($"Lỗi nộp lớp: {res.StatusCode}", "error");
            }
        }
    }

    private async Task HandleSubmitTongKet()
    {
        try
        {
            string apiUrl = TruongHocData.API_KetNoiSGD + "CongNhapDiem/NopTongKetC2_3";

            if (confirmType == "TK_CLASS")
            {
                var req = BuildTKRequest(tkSelectedLopTen, "");
                var res = await Http.PostAsJsonAsync(apiUrl, req);
                await ShowToast(res.IsSuccessStatusCode
                    ? $"Nộp tổng kết lớp {tkSelectedLopTen} thành công!"
                    : $"Lỗi: {res.StatusCode}", res.IsSuccessStatusCode ? "success" : "error");
                if (res.IsSuccessStatusCode) await TKViewClass(new LopItem { Id = tkSelectedLopId, Ten = tkSelectedLopTen });
            }
            else if (confirmType == "TK_STUDENT")
            {
                var req = BuildTKRequest(tkSelectedLopTen, tkTargetHsSo);
                var res = await Http.PostAsJsonAsync(apiUrl, req);
                await ShowToast(res.IsSuccessStatusCode
                    ? $"Nộp tổng kết học sinh {tkTargetHsSo} thành công!"
                    : $"Lỗi: {res.StatusCode}", res.IsSuccessStatusCode ? "success" : "error");
            }
            else if (confirmType == "TK_SELECTED")
            {
                var selected = tkDanhSachHocSinh.Where(h => h.IsSelected).ToList();
                int ok = 0, fail = 0;
                foreach (var hs in selected)
                {
                    var res = await Http.PostAsJsonAsync(apiUrl, BuildTKRequest(tkSelectedLopTen, hs.MaHocSinhSo));
                    if (res.IsSuccessStatusCode) ok++; else fail++;
                }
                await ShowToast($"Tổng kết thành công: {ok} HS, thất bại: {fail} HS.", fail > 0 ? "warning" : "success");
            }
        }
        finally { isLoading = false; StateHasChanged(); }
    }

    // ── Request builder: C2/3 Định Kỳ ──
    private object BuildRequestC2_3(string maLop, string maHsSo) => new
    {
        ma_truong_bo = maTruongBo,
        ma_cap_hoc   = selectedCapHoc,
        ma_lop       = maLop,
        ma_mon_hoc   = "",
        ma_hs_so     = maHsSo,
        hocky        = selectedHocKy,
        nam_hoc      = int.Parse(namHocYear)
    };

    // ── Request builder: C2/3 Tổng Kết ──
    private object BuildTKRequest(string maLop, string maHsSo) => new
    {
        ma_truong_bo = maTruongBo,
        ma_cap_hoc   = selectedCapHoc,
        ma_lop       = maLop,
        ma_hs_so     = maHsSo,
        hocky        = selectedHocKy,
        nam_hoc      = int.Parse(namHocYear)
    };

    /// <summary>
    /// Request builder: Cấp Tiểu Học – Đánh Giá Định Kỳ
    /// POST /CongNhapDiem/NopDanhGiaDinhKyC1
    /// dot_danh_gia: truyền rỗng để nộp tất cả đợt, hoặc truyền giá trị cụ thể.
    /// ma_mon_hoc:   truyền rỗng để nộp tất cả môn.
    /// </summary>
    private object BuildDinhKyC1Request(string maLop, string maHsSo, string dotDanhGia) => new
    {
        ma_truong_bo = maTruongBo,
        ma_lop       = maLop,
        ma_mon_hoc   = "",          // Truyền rỗng = nộp tất cả môn
        ma_hs_so     = maHsSo,      // Truyền rỗng = nộp cả lớp
        dot_danh_gia = dotDanhGia,  // Truyền rỗng = nộp tất cả đợt
        hocky        = selectedHocKy,
        nam_hoc      = int.Parse(namHocYear)
    };

    /// <summary>
    /// Request builder: Cấp Tiểu Học – Năng Lực Phẩm Chất
    /// POST /CongNhapDiem/NopNangLucPhamChatC1
    /// id_nguoi_nop: ID người đang đăng nhập.
    /// </summary>
    private object BuildNangLucC1Request(string maLop, string maHsSo) => new
    {
        ma_truong_bo = maTruongBo,
        ma_lop       = maLop,
        ma_hs_so     = maHsSo,      // Truyền rỗng = nộp cả lớp
        id_nguoi_nop = idNguoiDung,
        hocky        = selectedHocKy,
        nam_hoc      = int.Parse(namHocYear)
    };

    // ═══ TOAST ═══
    private async Task ShowToast(string msg, string type)
    {
        toastMessage = msg;
        toastClass   = type == "success" ? "toast-success" : type == "error" ? "toast-error" : "toast-warning";
        StateHasChanged();
        await Task.Delay(3500);
        ClearToast();
    }

    private void ClearToast() { toastMessage = ""; StateHasChanged(); }

